			end

			if not MainModule.is_game_active("TugOfWar") then
				return
			end

			if "OuterRingTemplate" ~= child.Name or tbl2[child] then
				return
			end
			tbl2[child] = true

			task.defer(function()
				local v14 = nil

				for _, child2 in pairs(impactFrames:GetChildren()) do
					local flag = child2.Name == "InnerTemplate" and child2.Position == child.Position

					if flag then
						flag = not child2:GetAttribute("Failed")
					end

					if flag then
						v14 = child2
						break
					end
				end

				if not v14 or v14:GetAttribute("Tweening") or v14:GetAttribute("Failed") then
					return
				end

				local ok, result = pcall(function()
					return require(ReplicatedStorage.Modules.HBGQTE)
				end)

				if not ok or not result then
					return
				end

				pcall(function()
					result.Pressed(false, { Inner = v14, Outer = child, Duration = 2, StartedAt = tick(), Data = {} })
				end)
			end)
		end)
