local function toggleExitDoorEsp(exitDoorESPEnabled)
	MainModule.ExitDoorESPEnabled = exitDoorESPEnabled

	if exitDoorESPEnabled then
		if MainModule.ExitDoorESPThread then
			task.cancel(MainModule.ExitDoorESPThread)
		end

		MainModule.ExitDoorESPThread = task.spawn(function()
			local tbl2 = {}

			local function fn4(arg)
				local boundingBox, v14 = arg:GetBoundingBox()
				local boxHandleAdornment = Instance.new("BoxHandleAdornment")
				boxHandleAdornment.Adornee = arg.PrimaryPart or arg:FindFirstChildWhichIsA("BasePart")
				if not boxHandleAdornment.Adornee then
					return nil
				end
				boxHandleAdornment.Size = v14
				boxHandleAdornment.Color3 = Color3.fromRGB(255, 255, 0)
				boxHandleAdornment.Transparency = 0.5
				boxHandleAdornment.AlwaysOnTop = true
				boxHandleAdornment.ZIndex = 10
				boxHandleAdornment.Parent = boxHandleAdornment.Adornee
				local billboardGui = Instance.new("BillboardGui")
				billboardGui.Adornee = boxHandleAdornment.Adornee
				billboardGui.Size = UDim2.new(0, 100, 0, 50)
				billboardGui.StudsOffset = Vector3.new(0, 3, 0)
				billboardGui.AlwaysOnTop = true
				billboardGui.Parent = boxHandleAdornment.Adornee
				local textLabel = Instance.new("TextLabel")
				textLabel.Size = UDim2.new(1, 0, 1, 0)
				textLabel.BackgroundTransparency = 1
				textLabel.Text = "EXIT DOOR"
				textLabel.TextColor3 = Color3.fromRGB(255, 255, 0)
				textLabel.TextScaled = true
				textLabel.Font = Enum.Font.SourceSansBold
				textLabel.Parent = billboardGui
				return { box = boxHandleAdornment, billboard = billboardGui, part = boxHandleAdornment.Adornee }
			end

			local v14

			while MainModule.ExitDoorESPEnabled do
				for _, v15 in pairs(tbl2) do
					if v15.box and (not v15.part or not v15.part.Parent) then
						pcall(function()
							v15.box:Destroy()
						end)

						pcall(function()
							v15.billboard:Destroy()
						end)
					end
				end

				local hideAndSeekMap = workspace:FindFirstChild("HideAndSeekMap")
				local v15 = hideAndSeekMap

				if v15 then
					local fn5 = v15

					while true do
						fn5 = function(arg)
							for _, child in pairs(arg:GetChildren()) do
								if not (child.Name ~= "EXITDOOR") and true == child:GetAttribute("ActuallyWorks") then
									if not tbl2[child] then
										local v16 = fn4(child)

										if v16 then
											tbl2[child] = v16
										end
									end
								end

								fn5(child)
							end
						end

						fn5(hideAndSeekMap)
						local exitTo = nil

						while true do
							task.wait(0.5)

							if MainModule.ExitDoorESPEnabled then
								for _, v16 in pairs(tbl2) do
									if v16.box and (not v16.part or not v16.part.Parent) then
										pcall(function()
											v16.box:Destroy()
										end)

										pcall(function()
											v16.billboard:Destroy()
										end)
									end
								end

								hideAndSeekMap = workspace:FindFirstChild("HideAndSeekMap")
								v14 = hideAndSeekMap
								if v14 then
									exitTo = 1
									break
								end
							else
								break
							end
						end

						if exitTo == 1 then
							fn5 = v14
							continue
						end
						break
					end

					return
				else
					task.wait(0.5)
				end
			end
		end)
	elseif MainModule.ExitDoorESPThread then
		task.cancel(MainModule.ExitDoorESPThread)
		MainModule.ExitDoorESPThread = nil
	end

	v12()

	if not nil then
	end
end

