MainModule.Fly = { Enabled = false, Speed = 50 }

MainModule.toggle_fly = function(arg, arg2)
	if arg then
		if MainModule.Fly.Enabled then
			return
		end
		MainModule.Fly.Enabled = true
		local v14 = MainModule.get_character()
		if not v14 then
			return
		end
		local getHumanoid = MainModule.get_humanoid
		local v15 = getHumanoid(v14)
		local getRootPart = MainModule.get_root_part
		local v16 = getRootPart(v14)
		if not (v15 and v16) then
			return
		end
		v15.UseJumpPower = false
		v15.AutoRotate = false
		v15.PlatformStand = true

		if MainModule.Fly.BodyVelocity then
			MainModule.Fly.BodyVelocity:Destroy()
		end

		local bodyVelocity = Instance.new("BodyVelocity")
		bodyVelocity.Name = "FlyBodyVelocity"
		bodyVelocity.MaxForce = Vector3.new(40000, 40000, 40000)
		bodyVelocity.Parent = v16
		MainModule.Fly.BodyVelocity = bodyVelocity

		MainModule.Fly.Connection = RunService.Heartbeat:Connect(function()
			if not MainModule.Fly.Enabled or not v14 or not v14.Parent then
				MainModule.toggle_fly(false, true)
				return
			end
			v16 = MainModule.get_root_part(v14)
			v15 = MainModule.get_humanoid(v14)
			if not v16 or not bodyVelocity or not v15 then
				MainModule.toggle_fly(false, true)
				return
			end
			local currentCamera = workspace.CurrentCamera
			local flag = not currentCamera

			if flag ~= nil then
				if flag ~= false then
					return
				end
			end

			local cFrame = currentCamera.CFrame
			local lookVector = cFrame.LookVector
			local rightVector = cFrame.RightVector
			local upVector = cFrame.UpVector
			local flag2 = false
			local vector = Vector3.new(0, 0, 0)

			if UserInputService:IsKeyDown(Enum.KeyCode.W) then
				vector += lookVector
				flag2 = true
			end

			if UserInputService:IsKeyDown(Enum.KeyCode.S) then
				vector -= lookVector
				flag2 = true
			end

			if UserInputService:IsKeyDown(Enum.KeyCode.A) then
				vector -= rightVector
				flag2 = true
			end

			if UserInputService:IsKeyDown(Enum.KeyCode.D) then
				vector += rightVector
				flag2 = true
			end

			local v17 = UserInputService:IsKeyDown(Enum.KeyCode.Space)

			if v17 ~= nil then
				if v17 ~= false then
					vector += upVector
					flag2 = true
				end
			end

			if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
				vector -= upVector
				flag2 = true
			end

			if not flag2 then
				local moveDirection = v15.MoveDirection

				if moveDirection.Magnitude > 0.1 then
					vector = lookVector * moveDirection.Z + rightVector * moveDirection.X + upVector * moveDirection.Y
					flag2 = true
				end
			end

			local flag3 = flag2

			if flag3 ~= nil then
				if flag3 ~= false then
					flag3 = vector.Magnitude > 0
				end
			end

			if flag3 then
				bodyVelocity.Velocity = vector.Unit * MainModule.Fly.Speed
			else
				bodyVelocity.Velocity = Vector3.new(0, 0, 0)
			end
		end)
	else
		if not MainModule.Fly.Enabled then
			return
		end
		MainModule.Fly.Enabled = false

		if MainModule.Fly.Connection then
			MainModule.Fly.Connection:Disconnect()
			MainModule.Fly.Connection = nil
		end

		if MainModule.Fly.BodyVelocity then
			MainModule.Fly.BodyVelocity:Destroy()
			MainModule.Fly.BodyVelocity = nil
		end

		local v14 = MainModule.get_character()

		if v14 then
			local v15 = MainModule.get_root_part(v14)

			if v15 then
				v15.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
			end

			local v16 = MainModule.get_humanoid(v14)

			if v16 then
				v16.UseJumpPower = true
				v16.AutoRotate = true
				v16.PlatformStand = false
			end
		end
	end

	if not arg2 then
		v12()
	end
end

