MainModule.is_seeker = function(arg)
	if not arg then
		error("devirt: symbolic index into a concrete VM table (key r900012), function 92 (at 0:<Reg {'n': 900012}>)")
	end

	return arg:GetAttribute("IsHunter") == true
end

