local function clearPlayerEsp(arg)
	if not arg then
		return
	end
	local v14 = MainModule.ESP.Players[arg]

	if v14 then
		if v14.Highlight then
			v14.Highlight.Adornee = nil

			pcall(function()
				v14.Highlight:Destroy()
			end)
