local function updatePlayerEsp(arg)
	if not arg or arg == localPlayer or not MainModule.ESPEnabled then
		return
	end
	local character = arg.Character
	if not character then
		MainModule.clear_player_esp(arg)
		return
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")

	if humanoid and humanoidRootPart and humanoid.Health > 0 then
		local tbl2 = MainModule.ESP.Players[arg]

		if not tbl2 then
			tbl2 = { Player = arg, Highlight = nil, Billboard = nil, Label = nil }
			MainModule.ESP.Players[arg] = tbl2
		end

		if not tbl2.Highlight then
			tbl2.Highlight = Instance.new("Highlight")
			tbl2.Highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			tbl2.Highlight.Parent = MainModule.ESP.Folder or CoreGui
		end

		tbl2.Highlight.Adornee = character
		local color = Color3.fromRGB(0, 120, 255)

		if MainModule.is_hider(arg) then
			color = Color3.fromRGB(0, 255, 0)
		elseif MainModule.is_seeker(arg) then
			color = Color3.fromRGB(255, 0, 0)
		end

		tbl2.Highlight.FillColor = color
		tbl2.Highlight.OutlineColor = color
		tbl2.Highlight.FillTransparency = 0.75
		tbl2.Highlight.OutlineTransparency = 0.2
		tbl2.Highlight.Enabled = true
		local flag = not tbl2.Billboard

		if flag ~= nil then
			if flag ~= false then
				tbl2.Billboard = Instance.new("BillboardGui")
				tbl2.Billboard.AlwaysOnTop = true
				tbl2.Billboard.Size = UDim2.new(0, 200, 0, 40)
				tbl2.Billboard.StudsOffset = Vector3.new(0, 2.5, 0)
				tbl2.Billboard.Parent = MainModule.ESP.Folder or CoreGui
				tbl2.Label = Instance.new("TextLabel")
				tbl2.Label.Size = UDim2.new(1, 0, 1, 0)
				tbl2.Label.BackgroundTransparency = 1
				tbl2.Label.TextSize = 14
				tbl2.Label.Font = Enum.Font.GothamBold
				tbl2.Label.TextStrokeTransparency = 0.5
				tbl2.Label.Parent = tbl2.Billboard
			end
		end

		tbl2.Billboard.Adornee = humanoidRootPart
		tbl2.Billboard.Enabled = true
		tbl2.Label.Text = arg.DisplayName or arg.Name
		tbl2.Label.TextColor3 = color
	else
		local v14 = MainModule.ESP.Players[arg]

		if v14 then
			if v14.Highlight then
				v14.Highlight.Enabled = false
				v14.Highlight.Adornee = nil
			end

			if v14.Billboard then
				v14.Billboard.Enabled = false
			end
		end
	end
end

MainModule.update_player_esp = updatePlayerEsp

local function togglePlayerEsp(espEnabled)
	MainModule.ESPEnabled = espEnabled
	MainModule.clear_esp()

	if espEnabled then
		MainModule.ESP.Folder = Instance.new("Folder")
		MainModule.ESP.Folder.Name = "NauruHub_ESP"
		MainModule.ESP.Folder.Parent = CoreGui

		for _, player in pairs(Players:GetPlayers()) do
			if player ~= localPlayer then
				MainModule.update_player_esp(player)
			end
		end

		MainModule.ESP.Connections.PlayerAdded = Players.PlayerAdded:Connect(function(player)
			if MainModule.ESPEnabled then
				MainModule.update_player_esp(player)
			end
		end)

		MainModule.ESP.Connections.PlayerRemoving = Players.PlayerRemoving:Connect(function(player)
			MainModule.clear_player_esp(player)
		end)

		MainModule.ESP.MainConnection = RunService.Heartbeat:Connect(function()
			if not MainModule.ESPEnabled then
				return
			end

			for k in pairs(MainModule.ESP.Players) do
				if k and k.Parent then
					MainModule.update_player_esp(k)
				else
					MainModule.clear_player_esp(k)
				end
			end
		end)
	end

	v12()
end

