MainModule.BalloonESPEnabled = false
MainModule.BalloonESPConnection = nil
MainModule.BalloonESPBoxes = {}

local function toggleBalloonEsp(balloonESPEnabled)
	MainModule.BalloonESPEnabled = balloonESPEnabled

	if MainModule.BalloonESPConnection then
		MainModule.BalloonESPConnection:Disconnect()
		MainModule.BalloonESPConnection = nil
	end

	for _, balloonESPBoxe in pairs(MainModule.BalloonESPBoxes) do
		pcall(function()
			balloonESPBoxe.box:Destroy()
		end)

		pcall(function()
			balloonESPBoxe.billboard:Destroy()
		end)
	end

	MainModule.BalloonESPBoxes = {}
	if not balloonESPEnabled then
		v12()
		return
	end

	local function fn6()
		for _, descendant in ipairs(Workspace:GetDescendants()) do
			local isBasePart = descendant.Name:lower():find("balloon") and descendant:IsA("BasePart")

			if isBasePart ~= nil then
				if isBasePart ~= false then
					isBasePart = not MainModule.BalloonESPBoxes[descendant]
				end
			end

			if isBasePart then
				local selectionBox = Instance.new("SelectionBox")
				selectionBox.Adornee = descendant
				selectionBox.Color3 = Color3.fromRGB(255, 100, 200)
				selectionBox.LineThickness = 0.05
				selectionBox.SurfaceTransparency = 0.5
				selectionBox.SurfaceColor3 = Color3.fromRGB(255, 100, 200)
				selectionBox.Parent = descendant
				local billboardGui = Instance.new("BillboardGui")
				billboardGui.Adornee = descendant
				billboardGui.Size = UDim2.new(0, 100, 0, 40)
				billboardGui.StudsOffset = Vector3.new(0, 3, 0)
				billboardGui.AlwaysOnTop = true
				billboardGui.Parent = descendant
				local textLabel = Instance.new("TextLabel")
				textLabel.Size = UDim2.new(1, 0, 1, 0)
				textLabel.BackgroundTransparency = 1
				textLabel.Text = "🎈 BALLOON"
				textLabel.TextColor3 = Color3.fromRGB(255, 100, 200)
				textLabel.TextScaled = true
				textLabel.Font = Enum.Font.SourceSansBold
				textLabel.Parent = billboardGui
				MainModule.BalloonESPBoxes[descendant] = { box = selectionBox, billboard = billboardGui }
			end
		end

		for k, balloonESPBoxe in pairs(MainModule.BalloonESPBoxes) do
			if not k.Parent then
				pcall(function()
					balloonESPBoxe.box:Destroy()
				end)

				pcall(function()
					balloonESPBoxe.billboard:Destroy()
				end)

				MainModule.BalloonESPBoxes[k] = nil
			end
		end
	end

	fn6()

	MainModule.BalloonESPConnection = RunService.Heartbeat:Connect(function()
		if not MainModule.BalloonESPEnabled then
			return
		end
		fn6()
	end)

	v12()
end

