local function tpToBalloon()
	local v14 = MainModule.get_character()
	local v15 = v14

	if v15 ~= nil then
		if v15 ~= false then
			v15 = MainModule.get_root_part(v14)
		end
	end

	if not v15 then
		v13()
		return
	end
	local v16 = nil
	local huge = math.huge

	for _, descendant in ipairs(Workspace:GetDescendants()) do
		if descendant.Name:lower():find("balloon") and descendant:IsA("BasePart") then
			local magnitude = (descendant.Position - v15.Position).Magnitude

			if huge > magnitude then
				v16 = descendant
				huge = magnitude
			end
		end
	end

	if v16 then
		MainModule.safe_teleport(v16.Position + Vector3.new(0, 3, 0))
		v12()
	else
		v13()
	end
end

MainModule.tp_to_balloon = tpToBalloon

