MainModule.SkySquidAntiFall = { Enabled = false }

MainModule.toggle_sky_squid_anti_fall = function(enabled)
	if MainModule.SkySquidAntiFall.Conn then
		MainModule.SkySquidAntiFall.Conn:Disconnect()
		MainModule.SkySquidAntiFall.Conn = nil
	end

	if MainModule.SkySquidAntiFall.Platform then
		MainModule.SkySquidAntiFall.Platform:Destroy()
		MainModule.SkySquidAntiFall.Platform = nil
	end

	MainModule.SkySquidAntiFall.Enabled = enabled

	if enabled then
		local function createPart()
			local v14 = MainModule.get_character()
			local v15 = v14 and MainModule.get_root_part(v14)
			if not v15 then
				return nil
			end
			local part = Instance.new("Part")
			part.Name = HttpService:GenerateGUID(false)
			part.Size = Vector3.new(10000, 1, 10000)
			part.Position = Vector3.new(v15.Position.X, v15.Position.Y - 5, v15.Position.Z)
			part.Anchored = true
			part.CanCollide = true
			part.Transparency = 0.5
			part.Parent = workspace
			return part
		end

		MainModule.SkySquidAntiFall.Platform = createPart()

		MainModule.SkySquidAntiFall.Conn = RunService.Heartbeat:Connect(function()
			if not MainModule.SkySquidAntiFall.Enabled then
				return
			end
			local flag = not (MainModule.SkySquidAntiFall.Platform and MainModule.SkySquidAntiFall.Platform.Parent)

			if flag ~= nil then
				if flag ~= false then
					MainModule.SkySquidAntiFall.Platform = createPart()
				end
			end
		end)
	end

	v12()
end

MainModule.PoleAim = { Enabled = false }

MainModule.toggle_pole_aim = function(enabled)
	MainModule.PoleAim.Enabled = enabled

	if MainModule.PoleAim.Connection then
		MainModule.PoleAim.Connection:Disconnect()
		MainModule.PoleAim.Connection = nil
	end

	if not enabled then
		v12()
		return
	end

	MainModule.PoleAim.Connection = RunService.Heartbeat:Connect(function()
		if not MainModule.PoleAim.Enabled then
			return
		end
		local character = localPlayer.Character
		if not character then
			return
		end
		local flag = false

		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Tool") and child.Name == "Pole" then
				flag = true
				break
			end
		end

		if not flag then
			return
		end
		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
		if not humanoidRootPart then
			return
		end
		local v14 = nil
		local huge = math.huge

		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= localPlayer and player.Character then
				local humanoidRootPart2 = player.Character:FindFirstChild("HumanoidRootPart")

				if humanoidRootPart2 then
					local magnitude = (humanoidRootPart2.Position - humanoidRootPart.Position).Magnitude

					if magnitude < huge then
						v14 = humanoidRootPart2
						huge = magnitude
					end
				end
			end
		end

		if v14 then
			local cframe = CFrame.lookAt(humanoidRootPart.Position, v14.Position)
			humanoidRootPart.CFrame = (cframe - cframe.Position) * CFrame.new(humanoidRootPart.Position)
		end
	end)

	v12()
end

